INSERT INTO player_role_map VALUES(18,'2024-25','FC26','measured:ST','ST',49,65,NULL,NULL,'0010161221334754655547X52',unistr('니스 베스트6 중 중앙 출전 3경기(앙제 8.7·브레스트 8.6·생테티엔 8.3) 통합. SofaScore 평균 y≈51.7(중앙), x≈65.3(전진). att-centre 24%가 최빈 존, 좌우 하프스페이스로 자유 드리프트(mid-left 18%). 3경기 4골3도움 xG평균 0.96. 게상이 "잘할 때"의 주 프로파일 — 중앙 스트라이커/세컨톱으로 좌측 하프스페이스 드리프트 자유가 있을 때 최고 산출. 표본 3경기로 그리드는 MEDIUM-HIGH\u000a⚠️ [2026-07-31 형식 정정] map25가 파이프 구분 29자(''00101|61221|…'')로 저장돼 있었다 — 툴의 decodeMap은 25자만 읽으므로 이 행은 NaN을 만들어 **모든 코사인 계산에서 무효**였다. 파이프만 제거해 25자로 정규화했다. ⚠️ **행 순서(방향)는 미검증**: 이 행의 기록된 툴 중심(y≈65.3=전진)과 그리드 행 중심(2.73)을 대조하면 **row0=자기진영**(프로젝트 규약 row0=최전방과 반대)일 가능성이 크다. 게상은 26/27 스쿼드 밖이라 현 프리셋에 영향이 없으나, **이 행을 인용하기 전에 SofaScore 원본에서 재도출할 것**.'),'AVL');
INSERT INTO player_role_map VALUES(18,'2024-25','FC26','measured:RM','RM',73,57,NULL,NULL,'001120135X002550137901444',unistr('니스 베스트6 중 우측 출전 3경기(랑스 8.5·마르세유 8.3·렌 8.1) 통합. 평균 y≈27(우측), x≈57.9. mid-right 32%·att-right 24%지만 att-centre+mid-centre 18%로 안쪽 침투 겸장 — 우측에서도 하프스페이스 진입이 잦은 인버티드형. 3경기 2골2도움 키패스 6. 니스에서는 우측 배치여도 중앙 관여가 유지됨\u000a⚠️ [2026-07-31 형식 정정] map25가 파이프 구분 29자(''00101|61221|…'')로 저장돼 있었다 — 툴의 decodeMap은 25자만 읽으므로 이 행은 NaN을 만들어 **모든 코사인 계산에서 무효**였다. 파이프만 제거해 25자로 정규화했다. ⚠️ **행 순서(방향)는 미검증**: 이 행의 기록된 툴 중심(y≈65.3=전진)과 그리드 행 중심(2.73)을 대조하면 **row0=자기진영**(프로젝트 규약 row0=최전방과 반대)일 가능성이 크다. 게상은 26/27 스쿼드 밖이라 현 프리셋에 영향이 없으나, **이 행을 인용하기 전에 SofaScore 원본에서 재도출할 것**.'),'AVL');
INSERT INTO player_role_map VALUES(18,'2025-26','FC26','measured','RM',79,58,NULL,NULL,'0111201126111360112X01344',unistr('빌라 45분+ 15경기 중 우측 14경기 통합(좌측 1경기 제외, 포지션-순수 규칙). 평균 y≈21.5(니스 우측 26.6보다 5p 더 측면 고정), att-right 32%+mid-right 31%+def-right 16% = 우측 레인에만 79%. 니스 대비 att-centre 10%로 중앙 관여 반감, def-right 16%로 수비 부담 배증. 산출 붕괴: 평점 8.42→6.44(니스 베스트6 대비), 니스 시즌 전체 7.30 대비도 -0.86. 터치 39→29, xG 0.62→0.17, xA 0.44→0.02, 키패스 1.5→0.4. 에메리 4-2-3-1 우측 윙어는 측면 고정+수비 트래킹 임무 — 게상의 강점(중앙 연계·하프스페이스 드리프트·박스 침투)이 구조적으로 차단된 배치. 실측 결론: 부적응이 아니라 역할 미스매치\u000a⚠️ [2026-07-31 형식 정정] map25가 파이프 구분 29자(''00101|61221|…'')로 저장돼 있었다 — 툴의 decodeMap은 25자만 읽으므로 이 행은 NaN을 만들어 **모든 코사인 계산에서 무효**였다. 파이프만 제거해 25자로 정규화했다. ⚠️ **행 순서(방향)는 미검증**: 이 행의 기록된 툴 중심(y≈65.3=전진)과 그리드 행 중심(2.73)을 대조하면 **row0=자기진영**(프로젝트 규약 row0=최전방과 반대)일 가능성이 크다. 게상은 26/27 스쿼드 밖이라 현 프리셋에 영향이 없으나, **이 행을 인용하기 전에 SofaScore 원본에서 재도출할 것**.'),'AVL');
INSERT INTO player_role_map VALUES(18,'2025-26','FC26','measured:CP-loan','CAM',40,62,NULL,NULL,'011002211132431X744312311',unistr('팰리스 임대 45분+ 7경기 통합(글라스너 3-4-2-1의 좌측 10번/세컨톱). 평균 y≈60.6(중앙-좌측), x≈62.3. mid-left 24%+att-left 17%가 최빈 — 니스 measured:ST 프로파일(중앙+좌하프스페이스 드리프트)과 방향 일치. 즉 팰리스는 게상을 "맞는 역할"에 썼다. 그러나 산출은 부분 회복에 그침: 45분+ 평점 6.77, 경기당 xG 0.17·xA 0.05·키패스 0.14 — 빌라 우측(xG 0.17)과 동일 수준, 니스 베스트6(xG 0.62·xA 0.44)에는 크게 미달. 2골 모두 컨퍼런스리그(즈린스키)·PL 교체 18분(울버햄튼), PL 선발 경기 평점 6.2~6.5. 결론: 역할 교정만으로 니스 산출이 복원되지 않음 — 니스 24-25 폭발에는 리그 수준·xG 초과달성(10골/xG7.77) 요인이 겹쳐 있었다는 방증. 4/9 이후 무릎 부상 9경기 결장으로 표본 확장 불가\u000a⚠️ [2026-07-31 형식 정정] map25가 파이프 구분 29자(''00101|61221|…'')로 저장돼 있었다 — 툴의 decodeMap은 25자만 읽으므로 이 행은 NaN을 만들어 **모든 코사인 계산에서 무효**였다. 파이프만 제거해 25자로 정규화했다. ⚠️ **행 순서(방향)는 미검증**: 이 행의 기록된 툴 중심(y≈65.3=전진)과 그리드 행 중심(2.73)을 대조하면 **row0=자기진영**(프로젝트 규약 row0=최전방과 반대)일 가능성이 크다. 게상은 26/27 스쿼드 밖이라 현 프리셋에 영향이 없으나, **이 행을 인용하기 전에 SofaScore 원본에서 재도출할 것**.'),'AVL');
INSERT INTO player_role_map VALUES(31,'2025-26','FC26','measured','GK',50,11,'gk_goalkeeper','Defend','0000000000000000010001X10','실측 6경기 평균 6.80. 중심(51.8,10.8). GK 커널 적합 gk_goalkeeper/Defend 0.961 > Balanced 0.953 > sweeper/Balanced 0.773 → 스위퍼형 아님. 자기진영 질량 1.00.','CHE');
INSERT INTO player_role_map VALUES(35,'2025-26','FC26','measured','LCB',31,35,'cb_bpd','Aggressive','0000023100661007X30045200','⭐ 실측이 포지션 서사를 정정: 6경기 평균 6.52, 중심(27.0,35.3). **LB(x=14) 최고 적합 fb_falseback/Balanced 0.717 < LCB(x=31) cb_bpd/Aggressive 0.930** → 쿠쿠렐라 후임 LB가 아니라 좌측 CB 프로필이다. 전방 0.12/자기진영 0.62.','CHE');
INSERT INTO player_role_map VALUES(33,'2025-26','FC26','measured','RCB',66,32,'cb_bpd','Aggressive','000000001101262023X400344','실측 6경기 평균 6.47, 중심(66.5,31.8). RCB cb_bpd/Aggressive **0.953** vs LCB 0.239 → **우측 전용**. 전방 0.05/자기진영 0.70 = 순수 수비형.','CHE');
INSERT INTO player_role_map VALUES(34,'2025-26','FC26','measured','RCB',66,38,'cb_bpd','Aggressive','0020002331137922X8X316440','실측 3경기(45분+ 표본 부족) 평균 6.47, 중심(52.7,37.6). RCB 0.744 > LCB 0.665 — 중앙 성향이라 백3의 중앙 CB 후보. 전방 0.14/자기진영 0.59.','CHE');
INSERT INTO player_role_map VALUES(32,'2025-26','FC26','measured','RB',86,46,'fb_att_wb','Support','00015111390004X0015900147','실측 6경기 평균 6.40, 중심(81.5,46.3). RB fb_att_wb/Support 0.862 > wingback/Support 0.830. 전방 0.34/자기진영 0.44 = 균형형 전진 풀백. 알론소 체계의 "폭 독점 윙백" 요구에 부합하는 유일한 보유 우측 인원.','CHE');
INSERT INTO player_role_map VALUES(36,'2025-26','FC26','measured','LDM',50,45,'dm_dlp','Roaming','000001333116X411574101111','실측 6경기 평균 7.00, 중심(47.6,44.5). **LDM(x=50) dm_dlp/Roaming 0.941** > RDM(x=61) 0.692 → 우측 피벗이 아니라 중앙 피벗. 전방 0.20/자기진영 0.40.','CHE');
INSERT INTO player_role_map VALUES(37,'2025-26','FC26','measured','LM',14,57,'wm_wideplm','Attack','311116X431386113522001000','⭐ 실측 6경기 평균 7.28(첼시 필드 최고), 중심(35.3,57.0) 좌측 편향. **LM(x=14) wm_wideplm/Attack 0.750 > LDM dm_dlp/Roaming 0.698 > CAM playmaker/Roaming 0.631** → 피벗 라벨보다 좌측 와이드 플레이메이커 형태에 가깝다. 전방 0.49/자기진영 0.21.','CHE');
INSERT INTO player_role_map VALUES(38,'2025-26','FC26','measured','RM',86,62,'wm_winger','Balanced','311264213X110191201410011','실측 6경기 평균 6.63, 중심(65.4,61.8). RM wm_winger/Balanced 0.875 > insidefwd/Balanced 0.847. LM 0.316 → 우측 전용. 전방 0.59/자기진영 0.20 = **터치라인형 윙어**(알론소 체계에 윙어 슬롯이 없다는 obs 모순의 실측 근거).','CHE');
INSERT INTO player_role_map VALUES(39,'2025-26','FC26','measured','RM',86,60,'wm_wideplm','Attack','11223225XX015640123200011','⭐⭐ 실측이 "CAM 10번" 라벨을 정정: 6경기 평균 6.82, 중심(65.0,59.9) **우측 편향**. **CAM(x=50) 최고 0.676(halfwinger/Balanced) < RM(x=86) wm_wideplm/Attack 0.845**. LM 0.152로 완전 부적합. 전방 0.59/자기진영 0.16 → 알론소의 2×10 중 **우측 축**.','CHE');
INSERT INTO player_role_map VALUES(40,'2025-26','FC26','measured','ST',50,61,'st_false9','Build-Up','243116X533232331212300110','⭐ 서사-실측 일치 사례: 6경기 평균 6.92, 중심(45.1,61.4). ST(x=50) st_false9/Build-Up 0.624 · **CAM 0.718(playmaker/Roaming)이 더 높다** → A1이 기록한 "내려오는 9번(dropping nine)" 서술을 실측이 지지. 전방 0.61/자기진영 0.18.','CHE');
INSERT INTO player_role_map VALUES(41,'2025-26','FC26','measured','RDM',61,52,'dm_dlp','Roaming','301170125901284002X800123','실측 3경기(표본 부족) 평균 7.33(최고). 중심(73.3,52.3). **RDM dm_dlp/Roaming 0.772 > RB fb_inverted/Attack 0.692** → 인버티드 윙백/하이브리드. 알론소가 트렌트에게 준 "inverted role" 지시의 첼시 대응 인원 후보.','CHE');
INSERT INTO player_role_map VALUES(42,'2025-26','FC26','measured','RM',86,58,'wm_widemid','Support','01354013780003X0025910001','실측 3경기(표본 부족) 평균 6.77, 중심(76.1,58.2). RM wm_widemid/Support 0.789 > winger/Balanced 0.746. 전방 0.51/자기진영 0.29 = 네투보다 복귀 성향이 큼.','CHE');
INSERT INTO player_role_map VALUES(13,'2026-27','FC26','measured','LM',14,56,'wm_insidefwd','Balanced','65321X9632564117410121100','⭐ 빌라 실측 그리드를 첼시 행으로 이관(사용자 지시). 근거 데이터는 **아스톤 빌라 25/26 실측**(에메리 체제 LW/인버티드)이며 첼시 실측이 아니다. 커널 적합: LW(x=28) w_insidefwd/Balanced 0.778 > **LM(x=14) wm_insidefwd/Balanced 0.733** > CAM 0.664 > RM 0.178(부적합). 전방 0.58/자기진영 0.21. **알론소 지시와의 대조**: 그는 로저스를 "포켓 위치 — 스트라이커 근처, 우리 10번 근처"로 규정(1티어 구단 공식)했는데 실측은 CAM(0.664)보다 좌측 인사이드(0.778)에 가깝다 → 알론소가 요구하는 중앙화는 **실측상 아직 근거가 없는 변화**다. 팔머와의 실측 겹침은 0.465로 낮아 좌우 분리 공존은 가능(팔머 중심 x=65 우측 / 로저스 좌측).','CHE');
INSERT INTO player_role_map VALUES(43,'2025-26','FC26','measured','GK',50,11,'gk_goalkeeper','Defend','0000000000000000010001X30','실측 6경기 평균 6.80, 중심(53.0,11.4). GK gk_goalkeeper/Defend 0.979 > Balanced 0.969 > sweeper 0.821 → 스위퍼형 아님.','LIV');
INSERT INTO player_role_map VALUES(44,'2025-26','FC26','measured','LCB',31,36,'cb_bpd','Aggressive','0010012100283102X52013610','실측 6경기 평균 7.15, 중심(38.1,35.7). **LCB 0.896 > CCB(x=50) 0.789** → 백3 중앙이 아니라 좌측 CB. 전방 0.10/자기진영 0.61.','LIV');
INSERT INTO player_role_map VALUES(45,'2025-26','FC26','measured','RCB',66,35,'cb_bpd','Aggressive','000000012100251013X201232','실측 6경기 평균 6.88, 중심(66.2,34.5). RCB cb_bpd/Aggressive 0.918. 전방 0.11/자기진영 0.67. ⚠️ 2026-07-01 레알 마드리드 자유이적 — **26/27 RCB 슬롯의 유일한 실측 기준선**으로 보존(대체자 판정용).','LIV');
INSERT INTO player_role_map VALUES(47,'2025-26','FC26','measured','LB',14,43,'fb_att_wb','Support','200009210043000X800043000','실측 2경기(표본 심각 부족 — 부상으로 3~5월 결장) 평균 6.15, 중심(17.7,42.6). LB fb_att_wb/Support 0.799. 로버트슨(→토트넘) 이탈로 26/27 1선발이나 표본 재수집 필요.','LIV');
INSERT INTO player_role_map VALUES(46,'2025-26','FC26','measured','RB',86,46,'fb_wingback','Support','00011010381125X0016700124','⭐ 미드필더의 RB 전용 사례 실측. 6경기 평균 7.05, 중심(77.6,46.4). RB fb_wingback/Support 0.843 · fb_inverted/Build-Up 0.814 / **RDM(x=61) dm_dlp/Roaming 0.800** → 미드필드 드리프트 서술을 지지. 다만 전방 0.26/자기진영 0.39로 **구스토(0.34/0.44)·캐시(0.33/0.47)보다 공격 관여가 낮다** → 3티어의 "트렌트급" 서술은 실측이 지지하지 않는다(트렌트형은 전방 질량이 높아야 함). 인버티드 축 참고 표본.','LIV');
INSERT INTO player_role_map VALUES(48,'2025-26','FC26','measured','RB',86,58,'fb_inverted','Attack','000680001X000170002500123','실측 4경기(표본 부족) 평균 6.42, 중심(85.8,58.3). RB **fb_inverted/Attack 0.905** · RM wm_insidefwd/Attack 0.875 → 풀백이 아니라 사실상 우측 공격 인원. 전방 0.54/자기진영 0.28 = 존스의 정반대. 같은 RB 슬롯에 두 유형이 공존.','LIV');
INSERT INTO player_role_map VALUES(49,'2025-26','FC26','measured','LDM',50,49,'dm_dlp','Roaming','112113X594266632466514432','실측 6경기 평균 6.77, 중심(52.9,48.6). **LDM(x=50) 0.782 > RDM(x=61) 0.677** → 중앙 피벗. 전방 0.38/자기진영 0.38 = 대칭형.','LIV');
INSERT INTO player_role_map VALUES(50,'2025-26','FC26','measured','LDM',50,49,'dm_dlp','Roaming','00321377622X9614887211211','실측 5경기 평균 6.64, 중심(47.1,49.2). LDM dm_dlp/Roaming **0.909** > RDM 0.639. 전방 0.33/자기진영 0.37. ⚠️ 그라베르베르흐와 동일 슬롯·동일 역할 최적 → 더블 피벗 두 축이 실측상 분화되지 않았다(슬롯 배분은 별도 판단 필요).','LIV');
INSERT INTO player_role_map VALUES(51,'2025-26','FC26','measured','RDM',61,57,'dm_dlp','Roaming','41324345XX237861326610110','⭐ 다중 슬롯 순회 실측(RM/RDM/CAM 36경기). 평균 7.02, 중심(59.8,57.0). **RDM dm_dlp/Roaming 0.812 > RM wm_wideplm/Attack 0.730 > CAM halfwinger/Balanced 0.673** → 세 라벨 중 실측 최적은 RDM. 전방 0.49/자기진영 0.23.','LIV');
INSERT INTO player_role_map VALUES(52,'2025-26','FC26','measured','CAM',50,59,'cam_halfwinger','Balanced','120425857X443564223210100','실측 5경기 평균 7.00, 중심(54.1,58.7). CAM cam_halfwinger/Balanced 0.785 > classic10/Versatile 0.711. RM 0.687. 전방 0.54/자기진영 0.19. £100m 영입 대비 부진 시즌이라는 서사와 달리 평점은 필드 상위.','LIV');
INSERT INTO player_role_map VALUES(53,'2025-26','FC26','measured','LM',14,64,'wm_insidefwd','Balanced','56831X8674768332323200100','실측 6경기 평균 6.52, 중심(42.5,63.6). **LM 0.648 · CAM 0.686 · ST 0.579** — 세 슬롯 모두 0.7 미만으로 어디에도 강하게 맞지 않는다(LM↔ST 겸업의 대가). 전방 0.59/자기진영 0.13.','LIV');
INSERT INTO player_role_map VALUES(54,'2025-26','FC26','measured','RM',86,71,'wm_insidefwd','Attack','011480003X000240001100000','⭐⭐ 실측 5경기 평균 **7.56**(리버풀 최고), 중심(82.6,71.3). RM **wm_insidefwd/Attack 0.961** — 이 프로젝트가 측정한 전 후보 중 최고치(하지무사 0.923·카타모 0.915 상회). 침투 서명 **전방 0.77/자기진영 0.06**은 하지무사(0.76/0.14)를 넘는다. ⚠️ 2026-07-01 FA로 이탈 — **obs#38 "뒷공간 반복 침투 빠른 우측 윙어" 브리프의 실측 원형(archetype)으로 보존**. 빌라 우측 후보 평가 시 이 그리드를 상한 기준선으로 쓸 수 있다.','LIV');
INSERT INTO player_role_map VALUES(31,'2026-27','FC26','projected','GK',50,11,'gk_goalkeeper','Defend',NULL,'실측 최적 그대로(0.961). 알론소 원칙의 "GK가 압박 시 +1 수적우위 제공"(obs#44)은 gk_sweeper를 함의하나 실측 적합 0.773으로 낮아 채택하지 않음 — 서사보다 실측 우선(불변규칙 #3).','CHE');
INSERT INTO player_role_map VALUES(35,'2026-27','FC26','projected','LCB',31,36,'cb_bpd','Aggressive',NULL,'실측 LCB 0.930. A2 조사의 "쿠쿠렐라 후임 LB" 제안을 실측이 반박(LB 0.717) — 그는 좌측 CB다. 백3 좌측 = 볼플레잉 CB(obs#58의 "볼플레잉 CB 2 + 강력한 CB 1" 중 하나).','CHE');
INSERT INTO player_role_map VALUES(34,'2026-27','FC26','projected','CCB',50,34,'cb_bpd','Aggressive',NULL,'⭐ **CCB 신설의 근거 인선**. 실측 CCB 0.873 > RCB 0.744 > LCB 0.665 — 중심 x 52.7로 정확히 중앙. 캐비앗: 45분+ 표본 3경기.','CHE');
INSERT INTO player_role_map VALUES(33,'2026-27','FC26','projected','RCB',66,32,'cb_bpd','Aggressive',NULL,'실측 RCB 0.953(CCB 0.669·LCB 0.424) = 우측 전용. 전방 0.05/자기진영 0.70으로 백3 중 가장 순수한 수비형 → obs#58의 "강력한 CB 1" 역할.','CHE');
INSERT INTO player_role_map VALUES(32,'2026-27','FC26','projected','RB',86,46,'fb_att_wb','Support',NULL,'실측 RB fb_att_wb/Support 0.862. 알론소 체계에서 폭을 독점하는 윙백(obs#46: 윙백은 크로서가 아니라 득점자, 프림퐁형). 전방 0.34/자기진영 0.44 = 전방 4인 중 유일한 수비 질량 공급자.','CHE');
INSERT INTO player_role_map VALUES(36,'2026-27','FC26','projected','LDM',50,45,'dm_dlp','Roaming',NULL,'실측 LDM 0.941(RDM 0.692). 알론소 원칙의 "피벗이 백라인 옆까지 내려와 압박 유인 후 관통"(obs#44)에 정합 — 자기진영 0.40.','CHE');
INSERT INTO player_role_map VALUES(41,'2026-27','FC26','projected','RDM',61,52,'dm_dlp','Roaming',NULL,'실측 RDM 0.772로 우측 피벗 유일 적합 인원(엔소는 RDM 0.361로 부적합). 알론소가 트렌트에게 준 "inverted role" 지시(obs#57)의 첼시 대응. ⚠️ 표본 3경기 — 이 처방의 가장 약한 칸.','CHE');
INSERT INTO player_role_map VALUES(13,'2026-27','FC26','projected','LM',14,56,'wm_insidefwd','Balanced',NULL,'좌측 10번. 실측 LM 0.733(CAM 0.664·RM 0.178). ⚠️ 두 겹의 캐비앗: ① 그리드가 빌라 25/26(에메리 체제) 것 ② **엔소가 LM 0.750으로 근소 우위**라 실측만 보면 엔소가 이 칸의 1순위다. 로저스를 두는 근거는 알론소의 명시 지시(obs#59, 1티어 구단 공식)와 £117m 영입 사실이며, 실측 근거는 아니다.','CHE');
INSERT INTO player_role_map VALUES(39,'2026-27','FC26','projected','RM',86,60,'wm_wideplm','Attack',NULL,'우측 10번. 실측 RM 0.845 ≫ CAM 0.676, LM 0.152. ⭐ 알론소는 그를 "포켓·10번 근처"로 말했지만 실측 중심 x=65는 **우측 편향**이다. 로저스와의 실측 겹침 0.465(낮음) → 좌우 분리 공존은 구조적으로 가능.','CHE');
INSERT INTO player_role_map VALUES(40,'2026-27','FC26','projected','ST',50,61,'st_false9','Build-Up',NULL,'실측 ST 0.624이나 CAM 0.718이 더 높다 = obs#59의 "내려오는 9번" 서사를 실측이 지지. false9/Build-Up이 그 성향에 가장 가까운 ST 역할. ⚠️ 로저스와 실측 겹침 **0.863(최고)** — 좌측 10번과 9번이 같은 공간을 쓴다. 알론소 체계의 실질 리스크 지점.','CHE');
